package com.cooper.lithic.data.backup

import java.nio.file.Files
import java.util.Base64
import org.junit.Assert.*
import org.junit.Test

class BackupJpegInspectionTest {
    @Test fun registered_baseline_and_progressive_jpeg_keep_their_original_container_and_dimensions() {
        for (progressive in listOf(false,true)) withJpeg(jpeg(progressive)) { file ->
            val original=file.readBytes()
            assertEquals(7 to 5,BackupJpegInspection.inspect(file))
            assertArrayEquals(original,file.readBytes())
        }
    }
    @Test fun incomplete_segments_missing_eoi_wrong_dimensions_and_unknown_frames_are_rejected() {
        val valid=jpeg(false)
        val frame=valid.indices.first { it+1<valid.size && valid[it]==0xff.toByte() && valid[it+1]==0xc0.toByte() }
        val cases=listOf(valid.copyOf(valid.size-1),valid+byteArrayOf(0),valid.copyOf().apply { this[frame+6]=0;this[frame+7]=0 },valid.copyOf().apply { this[frame+1]=0xc3.toByte() })
        for (bytes in cases) withJpeg(bytes) { file ->
            try { BackupJpegInspection.inspect(file);fail("Invalid JPEG container accepted") } catch (_: BackupMediaException) { }
        }
    }
    @Test fun byte_integrity_container_scan_does_not_claim_strict_entropy_validation() {
        val valid=jpeg(false)
        val sos=valid.indices.first { it+3<valid.size && valid[it]==0xff.toByte() && valid[it+1]==0xda.toByte() }
        val entropy=sos+2+((valid[sos+2].toInt() and 255)*256)+(valid[sos+3].toInt() and 255)
        // A container scanner cannot certify entropy correctness; preserve this limitation explicitly.
        val altered=valid.copyOf().apply { this[entropy]=(this[entropy].toInt() xor 1).toByte() }
        withJpeg(altered) { assertEquals(7 to 5,BackupJpegInspection.inspect(it)) }
    }
    // Original synthetic 7x5 RGB gradient, generated by the existing JDK 17 ImageIO.
    // RGB(x,y)=(x*31,y*47,90); default JPEG parameters, MODE_DEFAULT for progressive.
    // Baseline: 654 bytes, SHA-256 da170836bb2630908e946fc80da3352e071d8e88410cb588f7ac173635ea05f4.
    // Progressive: 554 bytes, SHA-256 fde98cbb8845e8863645fdbf31e7713760c9a8af4605a078f500866569f97a55.
    private fun jpeg(progressive:Boolean):ByteArray = Base64.getDecoder().decode(if(progressive)
        "" else
        "")
    private fun withJpeg(bytes:ByteArray,block:(java.io.File)->Unit) {
        val file=Files.createTempFile("backup-jpeg-", ".jpg").toFile()
        try { file.writeBytes(bytes);block(file) } finally { file.delete() }
    }
}
